drop policy if exists marketplace_reports_own_read on public.marketplace_reports;
create policy marketplace_reports_own_read on public.marketplace_reports for select to authenticated using (reporter_id = (select auth.uid()) or public.iqzodiac_is_admin());
drop policy if exists marketplace_favorites_own on public.marketplace_favorites;
create policy marketplace_favorites_own on public.marketplace_favorites for all to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
